<script setup lang="ts">
import EmployeeSearchSelect from '../../Components/EmployeeSearchSelect.vue';
import {Head,useForm} from '@inertiajs/vue3';import AdminLayout from '@core/Layouts/AdminLayout.vue';import {Button} from '@/components/ui/button';import {Input} from '@/components/ui/input';import {Label} from '@/components/ui/label';import DataTable,{type DataTableColumn} from '@core/Components/DataTable.vue';import type {Paginator, SelectOption } from '@core/types';
defineProps<{benefits:any[];deductions:any[];employee_adjustments:Paginator<any>;employeeOptions:SelectOption[]}>();const f=useForm({scope:'global',adjustment_type:'benefit',employee_id:'',name:'',code:'',calculation_type:'fixed',amount:0,percentage_base:'basic',effective_from:new Date().toISOString().slice(0,10),effective_to:'',auto_apply:false,taxable:true,pf_eligible:false});function save(){f.post(route('payroll.adjustments.store'))}
